/*
 * High-performance portfolio calculations using C extension
 *
 * Implements:
 *   risk   = sqrt(x^T * S * x)
 *   return = x^T * r
 *
 * The loops deliberately mirror the Python baseline's summation order
 * (S*x first, then x^T*(S*x)) so results agree to within ~1e-15.
 *
 * Two data paths are supported for the covariance matrix:
 *   - NumPy arrays: zero-copy (or one converting copy) through the C API.
 *   - Nested Python sequences (list of lists): walked directly in C.  This
 *     avoids NumPy's generic nested-sequence conversion, which dominates the
 *     runtime for matrices with tens of millions of entries.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Fetch one element as a double, fast path for exact PyFloat objects. */
static int fetch_double(PyObject *item, double *value) {
    if (PyFloat_CheckExact(item)) {
        *value = PyFloat_AS_DOUBLE(item);
        return 0;
    }
    *value = PyFloat_AsDouble(item);
    if (*value == -1.0 && PyErr_Occurred())
        return -1;
    return 0;
}

/* sqrt(x^T * S * x) with S held as a NumPy array (C-contiguous float64). */
static PyObject *risk_from_array(PyArrayObject *weights_array,
                                 PyArrayObject *cov_array) {
    const npy_intp n = PyArray_DIM(weights_array, 0);
    const double *restrict w   = (const double *)PyArray_DATA(weights_array);
    const double *restrict cov = (const double *)PyArray_DATA(cov_array);

    /* Step 1 + 2: temp = S*x, risk_squared = x^T*temp, same order as baseline. */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        const double *restrict row = cov + i * n;
        const double wi = w[i];
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j)
            row_sum += row[j] * w[j];
        risk_squared += wi * row_sum;
    }
    return PyFloat_FromDouble(sqrt(risk_squared));
}

/* sqrt(x^T * S * x) walking S directly as a sequence of sequences. */
static PyObject *risk_from_nested(PyObject *weights_obj, PyObject *cov_obj) {
    PyArrayObject *weights_array = (PyArrayObject *)PyArray_FROM_OTF(
        weights_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!weights_array)
        return NULL;

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be a 1-D array");
        Py_DECREF(weights_array);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    const double *restrict w = (const double *)PyArray_DATA(weights_array);

    PyObject *cov_seq = PySequence_Fast(cov_obj, "cov_matrix must be a sequence");
    if (!cov_seq) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PySequence_Fast_GET_SIZE(cov_seq) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and cov_matrix dimensions do not match");
        Py_DECREF(cov_seq);
        Py_DECREF(weights_array);
        return NULL;
    }

    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        PyObject *row_obj = PySequence_Fast_GET_ITEM(cov_seq, i);
        PyObject *row = PySequence_Fast(row_obj,
                                        "each covariance row must be a sequence");
        if (!row) {
            Py_DECREF(cov_seq);
            Py_DECREF(weights_array);
            return NULL;
        }
        if (PySequence_Fast_GET_SIZE(row) != n) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be a square 2-D array");
            Py_DECREF(row);
            Py_DECREF(cov_seq);
            Py_DECREF(weights_array);
            return NULL;
        }

        PyObject **items = PySequence_Fast_ITEMS(row);
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            double value;
            if (fetch_double(items[j], &value) < 0) {
                Py_DECREF(row);
                Py_DECREF(cov_seq);
                Py_DECREF(weights_array);
                return NULL;
            }
            row_sum += value * w[j];
        }
        Py_DECREF(row);

        risk_squared += w[i] * row_sum;
    }

    Py_DECREF(cov_seq);
    Py_DECREF(weights_array);

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    if (PyArray_Check(cov_obj)) {
        /* Zero-copy for C-contiguous float64 arrays, otherwise converts. */
        PyArrayObject *weights_array = (PyArrayObject *)PyArray_FROM_OTF(
            weights_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (!weights_array)
            return NULL;

        PyArrayObject *cov_array = (PyArrayObject *)PyArray_FROM_OTF(
            cov_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
        if (!cov_array) {
            Py_DECREF(weights_array);
            return NULL;
        }

        if (PyArray_NDIM(weights_array) != 1) {
            PyErr_SetString(PyExc_ValueError, "weights must be a 1-D array");
            Py_DECREF(weights_array);
            Py_DECREF(cov_array);
            return NULL;
        }
        if (PyArray_NDIM(cov_array) != 2 ||
            PyArray_DIM(cov_array, 0) != PyArray_DIM(cov_array, 1)) {
            PyErr_SetString(PyExc_ValueError,
                            "cov_matrix must be a square 2-D array");
            Py_DECREF(weights_array);
            Py_DECREF(cov_array);
            return NULL;
        }
        if (PyArray_DIM(cov_array, 0) != PyArray_DIM(weights_array, 0)) {
            PyErr_SetString(PyExc_ValueError,
                            "weights and cov_matrix dimensions do not match");
            Py_DECREF(weights_array);
            Py_DECREF(cov_array);
            return NULL;
        }

        PyObject *result = risk_from_array(weights_array, cov_array);
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return result;
    }

    return risk_from_nested(weights_obj, cov_obj);
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    PyArrayObject *weights_array = (PyArrayObject *)PyArray_FROM_OTF(
        weights_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!weights_array)
        return NULL;

    PyArrayObject *returns_array = (PyArrayObject *)PyArray_FROM_OTF(
        returns_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!returns_array) {
        Py_DECREF(weights_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must be 1-D arrays");
        Py_DECREF(weights_array);
        Py_DECREF(returns_array);
        return NULL;
    }
    if (PyArray_DIM(weights_array, 0) != PyArray_DIM(returns_array, 0)) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected_returns must have equal length");
        Py_DECREF(weights_array);
        Py_DECREF(returns_array);
        return NULL;
    }

    const npy_intp n = PyArray_DIM(weights_array, 0);
    const double *restrict w = (const double *)PyArray_DATA(weights_array);
    const double *restrict r = (const double *)PyArray_DATA(returns_array);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += w[i] * r[i];

    Py_DECREF(weights_array);
    Py_DECREF(returns_array);

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}
