sbx put /workspace/portfolio_optimized.py <<'EOF'
"""
Python wrapper for portfolio optimization C extension.
"""

import numpy as np

from portfolio_optimized_c import (
    portfolio_return_c as _portfolio_return_c,
    portfolio_risk_c as _portfolio_risk_c,
)


def portfolio_risk_c(weights, cov_matrix):
    """
    Calculate portfolio risk using C extension: sqrt(x^T * S * x)

    Args:
        weights: Portfolio weights (1D array-like)
        cov_matrix: Covariance matrix (2D array-like)
    Returns:
        Portfolio risk (scalar)
    """
    # The C extension handles both NumPy arrays (zero-copy) and plain nested
    # sequences.  Passing Python lists straight through lets C walk them
    # directly, which is far cheaper than first materializing an N x N array.
    if not isinstance(cov_matrix, np.ndarray):
        return _portfolio_risk_c(np.asarray(weights, dtype=np.float64),
                                 cov_matrix)
    return _portfolio_risk_c(np.ascontiguousarray(weights, dtype=np.float64),
                             np.ascontiguousarray(cov_matrix, dtype=np.float64))


def portfolio_return_c(weights, expected_returns):
    """
    Calculate expected portfolio return using C extension: weights^T * returns

    Args:
        weights: Portfolio weights (1D array-like)
        expected_returns: Expected returns (1D array-like)
    Returns:
        Expected return (scalar)
    """
    return _portfolio_return_c(np.ascontiguousarray(weights, dtype=np.float64),
                               np.ascontiguousarray(expected_returns,
                                                    dtype=np.float64))


__all__ = ['portfolio_risk_c', 'portfolio_return_c']
